import test from 'node:test';
import assert from 'node:assert/strict';
import {SchoolBrowser} from '../src/school-browser.mjs';
test('school browsing observes one native confirmation and resolves its exact identity without another click',async()=>{const b=new SchoolBrowser();try{await b.start({headed:false});await b.page.setContent('<button onclick="window.clicks=(window.clicks||0)+1;if(confirm(\'조회 조건을 적용할까요?\'))document.querySelector(\'output\').textContent=\'조회 완료\'">조회</button><output></output>');const screen=await b.snapshot(),result=await b.execute({action:'click',ref:screen.elements.find(e=>e.label==='조회').ref});assert.equal(result.actionPending,true);assert.equal(result.nativeDialog.message,'조회 조건을 적용할까요?');assert.equal((await b.snapshot()).nativeDialog.id,result.nativeDialog.id);await assert.rejects(b.execute({action:'dialog',decision:'accept',expectedId:'wrong',expectedMessage:result.nativeDialog.message}),e=>e.code==='DIALOG_MISMATCH');await b.execute({action:'dialog',decision:'accept',expectedId:result.nativeDialog.id,expectedMessage:result.nativeDialog.message});assert.match((await b.snapshot()).text,/조회 완료/);assert.equal(await b.page.evaluate(()=>window.clicks),1);}finally{await b.browser?.close();}});
test('a native final-action prompt cannot bypass document-bound authorization',async()=>{const b=new SchoolBrowser();try{await b.start({headed:false});await b.page.setContent('<button onclick="if(confirm(\'문서를 상신하시겠습니까?\'))window.submitted=true">기타 처리</button>');const screen=await b.snapshot(),result=await b.execute({action:'click',ref:screen.elements[0].ref});await assert.rejects(b.execute({action:'dialog',decision:'accept',expectedId:result.nativeDialog.id,expectedMessage:result.nativeDialog.message}),e=>e.code==='FINAL_DIALOG_AUTH_REQUIRED');await b.execute({action:'dialog',decision:'dismiss',expectedId:result.nativeDialog.id,expectedMessage:result.nativeDialog.message});assert.equal(await b.page.evaluate(()=>Boolean(window.submitted)),false);}finally{await b.browser?.close();}});
